def process_sector(sector_name, subsectors, sector_idx):
    print(f"\n{'='*60}")
    print(f"PROCESSING: {sector_name.upper()} ({len(subsectors)} subsectors)")
    print(f"{'='*60}")
    
    all_dfs = []
    stats = {'passed': 0, 'failed': 0}
    
    for sub_idx, subsector in enumerate(subsectors):
        classes = get_classes(subsector)
        df = generate_subsector(sector_name, subsector, classes, sector_idx, sub_idx)
        acc, f1, corr, imp, passed = validate_data(df, 'target')
        
        status = "✓" if passed else "✗"
        print(f"  {status} {subsector}: acc={acc:.2f} f1={f1:.2f} corr={corr:.2f} imp={imp:.2f}")
        
        if passed:
            stats['passed'] += 1
        else:
            stats['failed'] += 1
        
        all_dfs.append(df)
    
    sector_df = pd.concat(all_dfs, ignore_index=True)
    output_file = OUTPUT_DIR / f'{sector_name}.parquet'
    sector_df.to_parquet(output_file, index=False)
    
    print(f"\n  SAVED: {output_file}")
    print(f"  Rows: {len(sector_df):,}")
    print(f"  Passed: {stats['passed']}/{stats['passed']+stats['failed']}")
    
    return stats

if __name__ == "__main__":
    print("=" * 70)
    print("GENERATING 50 SECTORS x 50 SUBSECTORS = 2500 CLASSES")
    print("=" * 70)
    
    total_stats = {'passed': 0, 'failed': 0}
    
    for sector_idx, (sector_name, subsectors) in enumerate(ALL_SECTORS.items()):
        stats = process_sector(sector_name, subsectors, sector_idx)
        total_stats['passed'] += stats['passed']
        total_stats['failed'] += stats['failed']
    
    print("\n" + "=" * 70)
    print("COMPLETE")
    print("=" * 70)
    print(f"Total Passed: {total_stats['passed']}")
    print(f"Total Failed: {total_stats['failed']}")
    print(f"Pass Rate: {100*total_stats['passed']/(total_stats['passed']+total_stats['failed']):.1f}%")
